package com.abdulwaheed.smartelectricitypredictor.di

import com.abdulwaheed.smartelectricitypredictor.data.repository.AuthRepositoryImpl
import com.abdulwaheed.smartelectricitypredictor.domain.repository.AuthRepository
import dagger.Binds
import dagger.Module
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
abstract class AuthModule {
    @Binds
    @Singleton
    abstract fun bindAuthRepository(impl: AuthRepositoryImpl): AuthRepository
}

package com.abdulwaheed.smartelectricitypredictor.di

// This file originally provided Hilt bindings. The project uses a simple ServiceLocator
// instead of Hilt to avoid adding kapt/ksp in the build. Auth bindings were replaced
// by ServiceLocator in FirebaseModule.kt.

package com.abdulwaheed.smartelectricitypredictor.di

import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object FirebaseModule {
    @Provides
    @Singleton
    fun provideFirebaseAuth(): FirebaseAuth = FirebaseAuth.getInstance()

    @Provides
    @Singleton
    fun provideFirestore(): FirebaseFirestore = FirebaseFirestore.getInstance()
}

package com.abdulwaheed.smartelectricitypredictor.di

import com.abdulwaheed.smartelectricitypredictor.data.repository.AuthRepositoryImpl
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore

/**
 * Simple ServiceLocator used instead of Hilt for this project to provide Firebase instances
 * and repository singletons. This avoids adding kapt/ksp/hilt build-time plugins.
 */
object ServiceLocator {
    val auth: FirebaseAuth by lazy { FirebaseAuth.getInstance() }
    val firestore: FirebaseFirestore by lazy { FirebaseFirestore.getInstance() }
    val authRepository: AuthRepositoryImpl by lazy { AuthRepositoryImpl(auth) }
}

pluginManagement {
